struct Node{int left,right,leaf;};
std::vector<Node> nodes;std::array<std::vector<int>,32> cache;std::array<bool,32> known{};
const std::vector<int>& trees(int mask){if(known[mask])return cache[mask];known[mask]=true;auto&out=cache[mask];if(!(mask&(mask-1))){nodes.push_back({-1,-1,__builtin_ctz((unsigned)mask)});out.push_back(int(nodes.size()-1));return out;}int first=mask&-mask;for(int a=(mask-1)&mask;a;a=(a-1)&mask){int b=mask^a;if(!b||!(a&first))continue;auto A=trees(a),B=trees(b);for(int x:A)for(int y:B){nodes.push_back({x,y,-1});out.push_back(int(nodes.size()-1));}}return out;}
std::string text(int n){auto z=nodes[n];return z.leaf>=0?std::string(1,char('A'+z.leaf)):"("+text(z.left)+"+"+text(z.right)+")";}
template<class T>std::vector<T>read(const std::string&p,size_t size){std::ifstream f(p,std::ios::binary);if(!f)throw std::runtime_error("input_unset:"+p);std::vector<T>v(size);f.read((char*)v.data(),size*sizeof(T));if(size_t(f.gcount())!=size*sizeof(T)||f.peek()!=EOF)throw std::runtime_error("input_size:"+p);return v;}
int main(int argc,char**argv){try{if(argc!=3)throw std::runtime_error("arguments:directory groups_stride");int stride=std::stoi(argv[2]);if(stride!=8&&stride!=12)throw std::runtime_error("groups_stride_domain");std::string p=argv[1];auto w=read<uint8_t>(p+"/mixed-k64-weights.bin",256*128/2),x=read<uint8_t>(p+"/mixed-k64-activations.bin",64*128/2),s=read<uint8_t>(p+"/mixed-k64-scales.bin",64*stride);auto image=read<uint32_t>(p+"/mixed-k64-reduction-image.bin",256*64*2*12);float e2[]={0,.5f,1,1.5f,2,3,4,6,-0.f,-.5f,-1,-1.5f,-2,-3,-4,-6};auto nib=[](const auto&v,int row,int k){return(v[row*64+k/2]>>(4*(k&1)))&15;};auto trit=[](unsigned t){if(t==0)return 0;if(t==1)return 1;if(t==3)return -1;throw std::runtime_error("trit_domain");};const auto roots=trees(31);if(roots.size()!=105)throw std::runtime_error("tree_coverage");std::vector<std::array<uint64_t,4>>bad(roots.size());std::vector<float>eval(nodes.size());uint64_t wide_rtz_bad[4]={};std::vector<std::string>witness;
for(int c=0;c<64;c++)for(int row=0;row<256;row++)for(int inst=0;inst<2;inst++)for(int comp=0;comp<2;comp++){float v[5];int offset=((c*256+row)*2+inst)*12+comp*6;float target=std::bit_cast<float>(image[offset]);v[0]=inst?std::bit_cast<float>(image[offset-12]):0.f;for(int group=0;group<4;group++){float partial=0;for(int k=inst*64+group*16;k<inst*64+(group+1)*16;k++){unsigned a=nib(w,row,k);partial+=float(trit(comp?(a>>2):(a&3)))*e2[nib(x,c,k)];}unsigned code=s[c*stride+inst*4+group];if(code>126)throw std::runtime_error("scale_domain");int exp=code>>3,m=code&7;float alpha=exp?std::ldexp(1.f+float(m)/8,exp-7):float(m)/512;v[group+1]=partial*alpha;}
for(size_t i=0;i<nodes.size();i++){auto z=nodes[i];eval[i]=z.leaf>=0?v[z.leaf]:eval[z.left]+eval[z.right];}for(size_t i=0;i<roots.size();i++){float q=eval[roots[i]];if((q!=0||target!=0)&&std::bit_cast<uint32_t>(q)!=std::bit_cast<uint32_t>(target))bad[i][inst*2+comp]++;}double wide=0;for(float z:v)wide+=double(z);float rtz=float(wide);if(std::abs(double(rtz))>std::abs(wide))rtz=std::nextafter(rtz,0.f);if((rtz!=0||target!=0)&&std::bit_cast<uint32_t>(rtz)!=std::bit_cast<uint32_t>(target))wide_rtz_bad[inst*2+comp]++;if(witness.size()<8&&image[offset]!=image[offset+3]&&(target!=0||float(wide)!=0)){char line[1024];snprintf(line,sizeof(line),"{\"row\":%d,\"column\":%d,\"instruction\":%d,\"component\":%d,\"inputs\":[%.17g,%.17g,%.17g,%.17g,%.17g],\"native_bits\":%u,\"wide_rn_bits\":%u,\"wide_rtz_bits\":%u}",row,c,inst,comp,double(v[0]),double(v[1]),double(v[2]),double(v[3]),double(v[4]),image[offset],std::bit_cast<uint32_t>(float(wide)),std::bit_cast<uint32_t>(rtz));witness.emplace_back(line);}}
std::vector<size_t>order(roots.size());for(size_t i=0;i<order.size();i++)order[i]=i;auto count=[&](size_t i){uint64_t n=0;for(auto v:bad[i])n+=v;return n;};std::stable_sort(order.begin(),order.end(),[&](size_t a,size_t b){return count(a)<count(b);});printf("{\"status\":\"observed\",\"family\":\"all105 commutative binary RN-addition trees on C plus four weighted16-term sums\",\"scope\":\"saved native tape only; not a global native arithmetic theorem\",\"top\":[");for(size_t j=0;j<12;j++){size_t i=order[j];printf("%s{\"tree\":\"%s\",\"differences\":[%llu,%llu,%llu,%llu]}",j?",":"",text(roots[i]).c_str(),(unsigned long long)bad[i][0],(unsigned long long)bad[i][1],(unsigned long long)bad[i][2],(unsigned long long)bad[i][3]);}printf("],\"wide_rtz_differences\":[%llu,%llu,%llu,%llu],\"first_wide_rn_failures\":[",(unsigned long long)wide_rtz_bad[0],(unsigned long long)wide_rtz_bad[1],(unsigned long long)wide_rtz_bad[2],(unsigned long long)wide_rtz_bad[3]);for(size_t i=0;i<witness.size();i++)printf("%s%s",i?",":"",witness[i].c_str());puts("]}");return 0;}catch(const std::exception&e){fprintf(stderr,"%s\n",e.what());return 2;}}
